!function(){"use strict";document.addEventListener("DOMContentLoaded",function(){var e=document.getElementById("infyp-rest-chart");if(e&&"undefined"!=typeof Chart){var t=window.infypRestChart||{},r=Array.isArray(t.series)?t.series:[],a=t.labels||{};if(r.length){var n=r.map(function(e){return e.date}),s=r.map(function(e){return parseInt(e.success,10)||0}),o=r.map(function(e){return parseInt(e.failed,10)||0}),i=r.map(function(e){return parseInt(e.dry_run,10)||0});new Chart(e.getContext("2d"),{data:{labels:n,datasets:[{type:"bar",label:a.success||"Successful",data:s,backgroundColor:"rgba(0, 163, 42, 0.65)",borderColor:"rgba(0, 163, 42, 1)",borderWidth:1,stack:"requests"},{type:"bar",label:a.failed||"Failed",data:o,backgroundColor:"rgba(214, 54, 56, 0.65)",borderColor:"rgba(214, 54, 56, 1)",borderWidth:1,stack:"requests"},{type:"line",label:a.dryRun||"Dry runs",data:i,borderColor:"rgba(34, 113, 177, 1)",backgroundColor:"rgba(34, 113, 177, 0.15)",borderWidth:2,pointRadius:2,tension:.3,fill:!1}]},options:{responsive:!0,maintainAspectRatio:!1,interaction:{mode:"index",intersect:!1},plugins:{legend:{position:"top"},title:{display:!1}},scales:{x:{stacked:!0},y:{stacked:!0,beginAtZero:!0,ticks:{precision:0}}}}})}}})}();
